gTW(){return"\u0416\u043e\u049b. \u0422\u04e9\u043c\u0435\u043d \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b \u0436\u0435\u04a3\u0456\u043b \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 \u0431\u0430\u044f\u0443 \u0436\u04af\u0440\u0435\u0442\u0456\u043d \u043a\u04e9\u043b\u0456\u043a\u043a\u0435 \u0430\u0439\u043d\u0430\u043b\u0434\u044b\u0440\u043c\u0430\u0439\u0434\u044b."},
gTZ(){return"\u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0430\u0440\u0431\u0430\u0441\u044b\u0437 \u043c\u043e\u0442\u043e\u0446\u0438\u043a\u043b\u0434\u0456 \u0431\u0430\u0441\u044b\u043f \u043e\u0437\u0443\u0493\u0430 \u043c\u04af\u043c\u043a\u0456\u043d\u0434\u0456\u043a \u0431\u0435\u0440\u0435\u0434\u0456 \u043c\u0435?"},
gTY(){return"\u0418\u04d9. \u0411\u04af\u0439\u0456\u0440\u043b\u0456\u043a \u0442\u0456\u0440\u043a\u0435\u043c\u0435\u0441\u0456 \u0436\u043e\u049b \u0435\u043a\u0456 \u0434\u043e\u04a3\u0493\u0430\u043b\u0430\u049b\u0442\u044b \u043c\u043e\u0442\u043e\u0446\u0438\u043a\u043b\u0434\u0435\u0440 \u0431\u04b1\u043b \u0431\u0435\u043b\u0433\u0456\u0433\u0435 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0443\u0434\u0430\u043d \u0435\u0440\u0435\u043a\u0448\u0435\u043b\u0456\u043a \u0431\u043e\u043b\u044b\u043f \u0442\u0430\u0431\u044b\u043b\u0430\u0434\u044b."},
gU0(){return"\u0411\u0435\u043b\u0433\u0456\u0434\u0435\u0433\u0456 \u043d\u04e9\u043c\u0456\u0440 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u0434\u044b \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b \u0448\u0435\u0433\u0456 \u043c\u0435?"},
gU_(){return"\u0418\u04d9. \u0421\u0456\u0437 \u0431\u04b1\u0434\u0430\u043d \u0436\u044b\u043b\u0434\u0430\u043c \u0436\u04af\u0440\u0435 \u0430\u043b\u043c\u0430\u0439\u0441\u044b\u0437. \u041a\u04e9\u0440\u0456\u043d\u0443 \u043d\u0430\u0448\u0430\u0440 \u0431\u043e\u043b\u0441\u0430, \u049b\u0430\u0443\u0456\u043f\u0441\u0456\u0437 \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b \u0442\u04e9\u043c\u0435\u043d \u0431\u043e\u043b\u0443\u044b \u043c\u04af\u043c\u043a\u0456\u043d."},
gU2(){return"\u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0441\u0456\u0437\u0433\u0435 \u043a\u04e9\u0440\u0441\u0435\u0442\u0456\u043b\u0433\u0435\u043d \u0441\u0430\u043d\u043d\u0430\u043d \u0431\u0430\u044f\u0443 \u0436\u04af\u0440\u0443\u0434\u0456 \u0442\u0430\u043b\u0430\u043f \u0435\u0442\u0435 \u043c\u0435?"},
gU1(){return"\u0416\u043e\u049b. \u0411\u04b1\u043b \u0435\u04a3 \u0442\u04e9\u043c\u0435\u043d\u0433\u0456 \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b \u0448\u0435\u0433\u0456 \u0435\u043c\u0435\u0441, \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u0434\u044b \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b \u0448\u0435\u0433\u0456."},
gU4(){return"\u0416\u043e\u043b\u0430\u0443\u0448\u044b\u043d\u044b \u0448\u044b\u0493\u0430\u0440\u0443 \u04af\u0448\u0456\u043d \u049b\u0430\u0440\u0430\u043f\u0430\u0439\u044b\u043c \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 \u0431\u0456\u0440 \u043c\u0438\u043d\u0443\u0442\u049b\u0430 \u0442\u043e\u049b\u0442\u0430\u0442\u0443\u0493\u0430 \u0431\u043e\u043b\u0430 \u043c\u0430?"},
