gUY(){return"\u0416\u0435\u0431\u0435\u043b\u0435\u0440\u0433\u0435 \u049b\u0430\u0440\u0441\u044b \u0448\u0435\u04a3\u0431\u0435\u0440 \u0431\u043e\u0439\u044b\u043c\u0435\u043d \u0436\u04af\u0440\u0435 \u0430\u043b\u0430\u0441\u044b\u0437 \u0431\u0430?"},
gUX(){return"\u0416\u043e\u049b. \u041e\u043b\u0430\u0440 \u0442\u0435\u043a \u043a\u04e9\u0440\u0441\u0435\u0442\u043a\u0456\u043b\u0435\u0440\u043c\u0435\u043d \u043a\u04e9\u0440\u0441\u0435\u0442\u0456\u043b\u0433\u0435\u043d \u0431\u0430\u0493\u044b\u0442\u0442\u0430 \u0448\u0435\u04a3\u0431\u0435\u0440 \u0431\u043e\u0439\u044b\u043c\u0435\u043d \u049b\u043e\u0437\u0493\u0430\u043b\u0430\u0434\u044b."},
gV_(){return"\u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u0435\u04a3 \u0442\u04e9\u043c\u0435\u043d\u0433\u0456 \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u0442\u044b \u0431\u0435\u043b\u0433\u0456\u043b\u0435\u0439\u0434\u0456 \u043c\u0435?"},
gUZ(){return"\u0418\u04d9. \u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u0434\u044b \u0448\u0435\u043a\u0442\u0435\u0443 \u043c\u0435\u043d \u049b\u0430\u0443\u0456\u043f\u0441\u0456\u0437\u0434\u0456\u043a\u0442\u0456 \u0441\u0430\u049b\u0442\u0430\u0439 \u043e\u0442\u044b\u0440\u044b\u043f, \u0431\u0435\u043b\u0433\u0456\u043b\u0435\u043d\u0433\u0435\u043d \u043d\u0435\u043c\u0435\u0441\u0435 \u043e\u0434\u0430\u043d \u0436\u043e\u0493\u0430\u0440\u044b \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u043f\u0435\u043d \u0436\u04af\u0440\u0433\u0456\u0437\u0443\u0433\u0435 \u0431\u043e\u043b\u0430\u0434\u044b."},
gV1(){return"\u0411\u04b1\u043b \u0431\u0435\u043b\u0433\u0456 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u0434\u044b \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u0442\u044b \u0431\u0435\u043b\u0433\u0456\u043b\u0435\u0439\u0434\u0456 \u043c\u0435?"},
